    lta=(c[nlta:]-c[:-nlta]) / nlta
    sta_full=np.concatenate([np.full(nsta-1, sta[0] if len(sta)>0 else 0.0), sta])
    lta_full=np.concatenate([np.full(nlta-1, lta[0] if len(lta)>0 else 0.0), lta])
