from scipy.signal import butter, filtfilt


def parse_time(value: str) -> datetime:
    s = str(value)
    if s.endswith("Z"):
        s = s[:-1]
    return datetime.fromisoformat(s)


def bandpass(x: np.ndarray, fs: float, low: float = 1.0, high: float = 20.0, order: int = 4) -> np.ndarray:
    nyq = 0.5 * fs
    lowc = low / nyq
    highc = min(high / nyq, 0.99)
    if highc <= lowc:
        return x
    b, a = butter(order, [lowc, highc], btype="band")
    return filtfilt(b, a, x)


def moving_rms(x: np.ndarray, n: int) -> np.ndarray:
    if n <= 1:
        return np.abs(x)
    x2 = x * x
    c = np.cumsum(np.insert(x2, 0, 0.0))
    rms = (c[n:] - c[:-n]) / n
    rms = np.sqrt(rms)
    pad = np.full(n - 1, rms[0] if len(rms) > 0 else 0.0)
    return np.concatenate([pad, rms])


def sta_lta(x: np.ndarray, nsta: int, nlta: int) -> np.ndarray:
    x2 = x * x
    c = np.cumsum(np.insert(x2, 0, 0.0))
    sta = (c[nsta:] - c[:-nsta]) / nsta
    lta = (c[nlta:] - c[:-nlta]) / nlta
    sta_full = np.concatenate([np.full(nsta - 1, sta[0] if len(sta) > 0 else 0.0), sta])
    lta_full = np.concatenate([np.full(nlta - 1, lta[0] if len(lta) > 0 else 0.0), lta])
    eps = 1e-12
    ratio = sta_full / (lta_full + eps)
    ratio[:nlta] = np.nan
    return ratio


def aic_pick(x: np.ndarray, start: int, end: int) -> int:
    n = end - start
    if n < 20:
        return start
    xs = x[start:end]
    c = np.cumsum(xs)
    c2 = np.cumsum(xs * xs)
    aic = np.full(n, np.inf)
    for k in range(5, n - 5):
