        hold = int(0.1 * fs)
        for i in range(start, min(end, n - hold)):
            if ratio[i] > thr and np.all(ratio[i:i + hold] > thr * 0.8):
                return i
        if end <= start:
            return start
        sub = ratio[start:end]
        if np.any(np.isfinite(sub)):
            return int(start + np.nanargmax(sub))
        return int(start + np.argmax(env[start:end]))

    p_idx = pick_phase(ratio_z, env_z, tp, 3.0, 3.0, 2.5, nlta)
    p_idx = aic_pick(z, max(0, p_idx - int(0.6 * fs)), min(len(z), p_idx + int(0.6 * fs)))

    min_s = int(p_idx + 0.5 * fs)
    s_idx = pick_phase(ratio_h, env_h, ts, 5.0, 5.0, 2.3, min_s)
    s_idx = aic_pick(h, max(0, s_idx - int(0.8 * fs)), min(len(h), s_idx + int(0.8 * fs)))

    if s_idx <= min_s:
        end = len(ratio_h) - 1
        sub = ratio_h[min_s:end]
        if np.any(np.isfinite(sub)):
            s_idx = int(min_s + np.nanargmax(sub))
        else:
            s_idx = int(min_s + np.argmax(env_h[min_s:end]))

    return p_idx, s_idx


